<template><div class="add-to-cart"><template v-if="user"><form v-if="stock>0" :aria-busy="busy" @submit.prevent="add"><label :for="'add-quantity-'+productId">Số lượng mua</label><div><input :id="'add-quantity-'+productId" v-model.number="quantity" type="number" min="1" :max="stock" required :disabled="busy"/><button class="button button-primary" :disabled="busy" type="submit">{{ busy?'Đang thêm…':'Thêm vào giỏ hàng' }}</button></div></form><p v-if="success" role="status">Đã thêm vào giỏ. <RouterLink class="text-link" to="/cart">Xem giỏ hàng</RouterLink></p><p v-if="error" role="alert">{{ error }}</p></template><RouterLink v-else-if="stock>0" class="button button-primary" :to="{path:'/login',query:{redirect:'/products/'+productId}}">Đăng nhập để mua hàng</RouterLink></div></template>
<script setup>
import {ref} from 'vue';import {useAuth} from '../../composables/useAuth.js';import {usePage} from '../../legacy/navigation.js';import {marketplaceRequest as request} from '../../services/marketplace.js';
const props=defineProps({productId:{type:Number,required:true},stock:Number});const {user}=useAuth();const quantity=ref(1),busy=ref(false),error=ref(''),success=ref(false);
async function add(){if(busy.value)return;busy.value=true;error.value='';success.value=false;try{const result=await request('/account/cart/items','POST',{productId:props.productId,quantity:quantity.value});usePage().props.cartCount=result.quantity;success.value=true;}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<style scoped>.add-to-cart{margin:20px 0}.add-to-cart form>div{display:flex;gap:12px;flex-wrap:wrap;margin-top:8px}.add-to-cart input{font:inherit;min-height:48px;width:96px;border:1px solid var(--bm-control-border);border-radius:var(--bm-radius-control);padding:10px;background:var(--bm-surface)}.add-to-cart :focus-visible{outline:3px solid var(--bm-forest);outline-offset:3px}.add-to-cart p{line-height:1.6}</style>
